MAP
  NAME "simplemappr-binding-probe"
  FONTSET "/srv/simplemappr/Tests/smoke/fonts.txt"
  SIZE 800 400
  EXTENT -180 -90 180 90
  UNITS DD
  IMAGETYPE "png"
  IMAGECOLOR 235 245 250
  PROJECTION
    "init=epsg:4326"
  END
  OUTPUTFORMAT
    NAME "png"
    DRIVER "AGG/PNG"
    MIMETYPE "image/png"
    IMAGEMODE RGB
  END
  OUTPUTFORMAT
    NAME "svg"
    DRIVER "CAIRO/SVG"
    MIMETYPE "image/svg+xml"
    IMAGEMODE RGB
  END
  OUTPUTFORMAT
    NAME "tif"
    DRIVER "GDAL/GTiff"
    MIMETYPE "image/tiff"
    IMAGEMODE RGB
  END
  SYMBOL
    NAME "circle"
    TYPE ELLIPSE
    FILLED TRUE
    POINTS
      1 1
    END
  END
  LAYER
    NAME "land"
    TYPE POLYGON
    STATUS ON
    DATA "/srv/simplemappr/mapserver/maps/10m_physical/ne_10m_land.shp"
    PROJECTION
      "init=epsg:4326"
    END
    CLASS
      STYLE
        COLOR 225 222 210
        OUTLINECOLOR 90 90 90
        WIDTH 0.4
      END
    END
  END
  LAYER
    NAME "provinces"
    TYPE POLYGON
    STATUS ON
    DATA "/srv/simplemappr/mapserver/maps/10m_cultural/10m_cultural/ne_10m_admin_1_states_provinces.shp"
    PROJECTION
      "init=epsg:4326"
    END
    CLASS
      STYLE
        COLOR 210 225 205
        WIDTH 0.4
      END
    END
  END
  LAYER
    NAME "lakes"
    TYPE POLYGON
    STATUS ON
    DATA "/srv/simplemappr/mapserver/maps/10m_physical/ne_10m_lakes.shp"
    PROJECTION
      "init=epsg:4326"
    END
    CLASS
      STYLE
        COLOR 235 245 250
        WIDTH 0.4
      END
    END
  END
  LAYER
    NAME "countries"
    TYPE LINE
    STATUS ON
    DATA "/srv/simplemappr/mapserver/maps/10m_cultural/10m_cultural/ne_10m_admin_0_map_units.shp"
    PROJECTION
      "init=epsg:4326"
    END
    CLASS
      STYLE
        COLOR 100 100 100
        WIDTH 0.4
      END
    END
  END
  LAYER
    NAME "province-borders"
    TYPE LINE
    STATUS ON
    DATA "/srv/simplemappr/mapserver/maps/10m_cultural/10m_cultural/ne_10m_admin_1_states_provinces_lines.shp"
    PROJECTION
      "init=epsg:4326"
    END
    CLASS
      STYLE
        COLOR 120 110 100
        WIDTH 0.4
      END
    END
  END
  LAYER
    NAME "Toronto"
    TYPE POINT
    STATUS ON
    PROJECTION
      "init=epsg:4326"
    END
    FEATURE
      POINTS
        -79.3832 43.6532
      END
    END
    CLASS
      STYLE
        SYMBOL "circle"
        SIZE 12
        COLOR 210 30 35
        OUTLINECOLOR 255 255 255
        WIDTH 1
      END
    END
  END
  LAYER
    NAME "accent-label"
    TYPE POINT
    STATUS ON
    PROJECTION
      "init=epsg:4326"
    END
    FEATURE
      POINTS
        -60 35
      END
      TEXT "Montréal"
    END
    CLASS
      LABEL
        TYPE TRUETYPE
        FONT "dejavu"
        ENCODING "UTF-8"
        SIZE 14
        COLOR 10 10 10
        POSITION CC
        FORCE TRUE
      END
    END
  END
END
